import re
from collections import Counter
p='/workspace/text.gcode'
c=Counter()
first={}
xs=[];ys=[];zs=[]
for i,l in enumerate(open(p),1):
    s=l.strip()
    if not s: continue
    cmd=s.split()[0]
    c[cmd]+=1
    first.setdefault(cmd,i)
    if cmd in ('G0','G1','G2','G3'):
        for w in re.findall(r'([XYZE])(-?\d+\.?\d*)',s):
            if w[0]=='X': xs.append(float(w[1]))
            if w[0]=='Y': ys.append(float(w[1]))
            if w[0]=='Z': zs.append(float(w[1]))
print('total lines',i)
print(c.most_common())
print('first',first)
print('X',min(xs),max(xs),'Y',min(ys),max(ys),'Z',min(zs),max(zs))
