python3 - <<'PY'
import re
p='/workspace/text.gcode'
lines=open(p).read().splitlines()
names={0:'Embossed text',1:'Shape-Box'}
blocks=[]
cur=None
for i,l in enumerate(lines,1):
    s=l.strip()
    m=re.match(r'M486 S(\d+)$',s)
    if m:
        cur={'obj':int(m.group(1)),'start':i,'moves':[]}
    elif s=='M486 S-1':
        if cur is not None:
            cur['end']=i; blocks.append(cur); cur=None
    elif cur is not None and (s.startswith('G1 ') or s.startswith('G0 ') or s.startswith('G2 ') or s.startswith('G3 ')):
        cur['moves'].append((i,s))
for b in blocks:
    mv=b['moves']
    xs=[];ys=[];zs=[];es=[]
    for i,s in mv:
        for w in re.findall(r'([XYZEF])(-?\d+\.?\d*)',s):
            if w[0]=='X': xs.append(float(w[1]))
            if w[0]=='Y': ys.append(float(w[1]))
            if w[0]=='Z': zs.append(float(w[1]))
            if w[0]=='E': es.append(float(w[1]))
    def rng(a): return (min(a),max(a)) if a else None
    print(f"{names[b['obj']]:14s} lines {b['start']}-{b['end']} moves {len(mv)}")
    print('   X',rng(xs),'Y',rng(ys),'Z',rng(zs),'E',rng(es))
